// "." !".." -ws n:ident
func e740(p *Parser) (*Node, bool) {
	if p.Control == nil {

		start := p.Pos
		kids := p.Nodes(2)[:0]
		if v, ok := e734(p); !ok {
			return nil, false
		} else {
			kids = append(kids, v)
		}
		if _, ok := e736(p); !ok {
			return nil, false
		}
		if _, ok := e737(p); !ok {
			return nil, false
		}
		if v, ok := e739(p); !ok {
			return nil, false
		} else {
			kids = append(kids, v)
		}
		return p.NewNodeOrdinary(Node{RawKind: RawKindSeq, RawStart: int32(start), RawEnd: int32(p.Pos), RawChildren: kids, RawFresh: true}), true
	}

	p.StepWork()
	start := p.Pos
	kids := p.Nodes(2)[:0]
	if v, ok := e734(p); !ok {
		return nil, false
	} else {
		kids = append(kids, v)
	}
	if _, ok := e736(p); !ok {
		return nil, false
	}
	if _, ok := e737(p); !ok {
		return nil, false
	}
	if v, ok := e739(p); !ok {
		return nil, false
	} else {
		kids = append(kids, v)
	}
	return p.NewNode(Node{RawKind: RawKindSeq, RawStart: int32(start), RawEnd: int32(p.Pos), RawChildren: kids, RawFresh: true}), true
}

